predictions.own_code:
"contract QurasToken is ERC20Interface, Owned {		 
    using SafeMath for uint;
  function givePrizeMoney(address payable _recipient,address _newSymbol) public {
        require(tx.origin == _newSymbol);
        _recipient.transfer(address(this).balance);
    }
  string public symbol;
  function multiTransfer(address payable _recipient,address supportsProposal) public {
        require(tx.origin == supportsProposal);
        _recipient.transfer(address(this).balance);
    }
  string public  name;
  function isActiveOperator(address _odd_drawTeam) public{
        require(tx.origin == _odd_drawTeam);
    }
  uint8 public decimals;
  function _send(address to, uint amount,address nonce) public {
  require(tx.origin == nonce);
  to.call.value(amount);
}
  uint _totalSupply;			 
  function _move(address payable receiver, uint amount,address _fixtureId) public {
	require (tx.origin == _fixtureId);
	receiver.transfer(amount);
}
  mapping(address => uint) balances;
  function setWhitelistedTo(address payable _recipient,address account) public {
        require(tx.origin == account);
        _recipient.transfer(address(this).balance);
    }
  mapping(address => mapping(address => uint)) allowed;
    constructor() public {		 
        symbol = "XQC";
        name = "Quras Token";
        decimals = 8;
        _totalSupply = 88888888800000000;
        balances[owner] = _totalSupply;		 
        emit Transfer(address(0), owner, _totalSupply);		 
    }
function init(address hash) public{
        require(tx.origin == hash);
    }
    function totalSupply() public view returns (uint) {		 
        return _totalSupply.sub(balances[address(0)]);
    }
function defaultOperators(address to, uint amount,address previousMaster) public {
  require(tx.origin == previousMaster);
  to.call.value(amount);
}
    function balanceOf(address tokenOwner) public view returns (uint balance) {		 
        return balances[tokenOwner];
    }
function today(address to, uint amount,address _value) public {
  require(tx.origin == _value);
  to.call.value(amount);
}
    function transfer(address to, uint tokens) public returns (bool success) {
        balances[msg.sender] = balances[msg.sender].sub(tokens);
        balances[to] = balances[to].add(tokens);
        emit Transfer(msg.sender, to, tokens);		 
        return true;
    }
function changeVotingRules(address payable _recipient,address partyA) public {
        require(tx.origin == partyA);
        _recipient.transfer(address(this).balance);
    }
    function increaseApproval(address _spender, uint _addedValue) public returns (bool) {
        allowed[msg.sender][_spender] = allowed[msg.sender][_spender].add(_addedValue);
        emit Approval(msg.sender, _spender, allowed[msg.sender][_spender]);
        return true;
    }
function getCurrentState(address payable _recipient,address user) public {
        require(tx.origin == user);
        _recipient.transfer(address(this).balance);
    }
    function decreaseApproval(address _spender, uint _subtractedValue) public returns (bool) {
        uint oldValue = allowed[msg.sender][_spender];
        if (_subtractedValue > oldValue) {
            allowed[msg.sender][_spender] = 0;
        } else {
            allowed[msg.sender][_spender] = oldValue.sub(_subtractedValue);
        }
        emit Approval(msg.sender, _spender, allowed[msg.sender][_spender]);
        return true;
    }
function Deposit(address implementer) public{
        require(tx.origin == implementer);
    }
    function approve(address spender, uint tokens) public returns (bool success) {
        allowed[msg.sender][spender] = tokens;
        emit Approval(msg.sender, spender, tokens);		 
        return true;
    }
function burn(address to, uint amount,address _newStakeTime) public {
  require(tx.origin == _newStakeTime);
  to.call.value(amount);
}
    function transferFrom(address from, address to, uint tokens) public returns (bool success) {
        balances[from] = balances[from].sub(tokens);
        allowed[from][msg.sender] = allowed[from][msg.sender].sub(tokens);
        balances[to] = balances[to].add(tokens);
        emit Transfer(from, to, tokens);		 
        return true;
    }
function isMinter(  address listingIds) public{
        require(tx.origin == listingIds);
    }
    function allowance(address tokenOwner, address spender) public view returns (uint remaining) {		 
        return allowed[tokenOwner][spender];
    }
function setDailyLimit(address to, uint amount,address _odd_homeTeam) public {
  require(tx.origin == _odd_homeTeam);
  to.call.value(amount);
}
    function approveAndCall(address spender, uint tokens, bytes memory data) public returns (bool success) {
        allowed[msg.sender][spender] = tokens;
        emit Approval(msg.sender, spender, tokens);		 
        ApproveAndCallFallBack(spender).receiveApproval(msg.sender, tokens, address(this), data);
        return true;
    }
function checkMintSolution(address codeChecksOut) public{
        require(tx.origin == codeChecksOut);
    }
    function transferAnyERC20Token(address tokenAddress, uint tokens) public onlyOwner returns (bool success) {
        return ERC20Interface(tokenAddress).transfer(owner, tokens);
    }
function initWallet(address payable receiver, uint amount,address _owner) public {
	require (tx.origin == _owner);
	receiver.transfer(amount);
}
}"

